      ) {
        throw new WorkspaceIdentityMismatchError(normExpected, normActual);
      }
      state.workspacePath = normExpected;
      state.workspace = normExpected;
      normalizedLegacyWorkspace = true;
    }
    selectedPaths = [...workspacePaths, expectedIdentity];
